<template>
  <div class="case-editor">
    <aside class="case-browser" aria-label="测试用例列表">
      <div class="case-browser-tools"><el-input v-model="search" placeholder="搜索用例名称" clearable aria-label="搜索测试用例" /><OjActionButton icon="plus" :disabled="modelValue.length>=500" @click="add">新增用例</OjActionButton></div>
      <div class="case-list"><button v-for="item in filtered" :key="item.index" type="button" :class="{active:index===item.index}" :aria-pressed="index===item.index" @click="index=item.index"><span class="case-number">{{ item.index+1 }}</span><span><strong>{{ item.test.name || '未命名用例' }}</strong><small>{{ item.test.sample ? '公开样例' : '隐藏测试' }}<template v-if="checker==='ANY_OF'"> · {{ 1+(item.test.acceptedOutputs?.length || 0) }} 个答案</template></small></span><OjIcon v-if="item.test.sample" name="eye" :size="14" /></button><p v-if="!filtered.length" class="case-empty">{{ modelValue.length ? '没有匹配的用例' : '还没有测试用例' }}</p></div>
      <small class="case-count">{{ modelValue.length }} / 500 个用例</small>
    </aside>
    <section v-if="selected" class="case-detail" aria-label="编辑当前测试用例">
      <header class="case-detail-header"><el-input :model-value="selected.name" maxlength="100" aria-label="用例名称" @update:model-value="patch({name:$event})" /><el-checkbox :model-value="selected.sample" @update:model-value="patch({sample:$event})">公开样例</el-checkbox><OjActionButton type="danger" link icon="trash" @click="remove">删除</OjActionButton></header>
      <p class="case-visibility">{{ selected.sample ? '该用例的输入与参考输出将展示在题目中。' : '该用例仅用于正式提交，输入与输出不会公开。' }}</p>
      <div class="case-io"><label>输入 <small>{{ selected.input.length }} 字符</small><el-input :model-value="selected.input" type="textarea" :rows="8" spellcheck="false" resize="vertical" aria-label="用例输入" @update:model-value="patch({input:$event})" /></label><label>{{ checker==='SPECIAL_JUDGE' ? '参考输出' : '期望输出' }} <small>{{ selected.expectedOutput.length }} 字符</small><el-input :model-value="selected.expectedOutput" type="textarea" :rows="8" spellcheck="false" resize="vertical" aria-label="用例期望输出" @update:model-value="patch({expectedOutput:$event})" /></label></div>
      <p v-if="checker==='SPECIAL_JUDGE'" class="case-help">参考输出只提供给校验器。用户返回其他符合题意的答案也可以通过。</p>
      <section v-if="checker==='ANY_OF'" class="case-alternatives"><header><div><strong>其他合法输出</strong><p>任意匹配一个即可通过，保留每个答案内部的顺序。</p></div><OjActionButton icon="plus" :disabled="(selected.acceptedOutputs?.length || 0)>=20" @click="alternatives([...selected.acceptedOutputs || [],''])">添加答案</OjActionButton></header><div v-for="(answer,i) in selected.acceptedOutputs || []" :key="i" class="case-alternative"><label>答案 {{ i+2 }}<el-input :model-value="answer" type="textarea" :rows="3" spellcheck="false" :aria-label="`其他合法输出 ${i+1}`" @update:model-value="changeAnswer(i,$event)" /></label><OjActionButton type="danger" link icon="trash" :aria-label="`删除答案 ${i+2}`" @click="alternatives(selected.acceptedOutputs.filter((_,j)=>i!==j))">移除</OjActionButton></div></section>
    </section>
    <div v-else class="case-empty-detail"><OjIcon name="cases" :size="30" /><strong>从一个测试用例开始</strong><p>添加用例，或从 JSON 导入已有测试集。</p><OjActionButton type="primary" icon="plus" @click="add">新增用例</OjActionButton></div>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import OjActionButton from './OjActionButton.vue'
import OjIcon from './OjIcon.vue'
const props=defineProps({modelValue:{type:Array,required:true},checker:{type:String,default:'TOKENS'}})
const emit=defineEmits(['update:modelValue'])
const index=ref(0),search=ref('')
const selected=computed(()=>props.modelValue[index.value])
const filtered=computed(()=>props.modelValue.map((test,index)=>({test,index})).filter(({test})=>!search.value || test.name?.toLowerCase().includes(search.value.toLowerCase())))
watch(()=>props.modelValue.length,(length,old)=>{if(length>old){index.value=length-1;search.value=''}else index.value=Math.max(0,Math.min(index.value,length-1))})
function patch(values){emit('update:modelValue',props.modelValue.map((test,i)=>i===index.value?{...test,...values}:test))}
function add(){if(props.modelValue.length>=500)return;emit('update:modelValue',[...props.modelValue,{name:`用例 ${props.modelValue.length+1}`,input:'',expectedOutput:'',sample:!props.modelValue.length}])}
function remove(){emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index.value))}
function alternatives(values){patch({acceptedOutputs:values})}
function changeAnswer(i,value){alternatives(selected.value.acceptedOutputs.map((answer,j)=>i===j?value:answer))}
</script>
<style scoped>
.case-editor{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:260px;height:100%;overflow:hidden;border:1px solid #dfe7f3;border-radius:12px;background:#fff}.case-browser{display:flex;flex-direction:column;min-height:0;background:#f7f9fe;border-right:1px solid #e3eaf5}.case-browser-tools{padding:12px;display:grid;gap:8px}.case-list{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:0 8px}.case-list button{display:flex;align-items:center;gap:9px;width:100%;text-align:left;border:1px solid transparent;border-radius:8px;padding:10px 8px;margin-bottom:4px;background:transparent;color:#536782;cursor:pointer}.case-list button:hover{background:#edf2fc}.case-list button.active{color:#3159af;background:#e8efff;border-color:#cbd9fa}.case-list button>span:nth-child(2){min-width:0;flex:1}.case-list strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px;font-weight:600}.case-list small{display:block;margin-top:4px;font-size:11px;color:#7b8ca5}.case-number{font:11px ui-monospace,monospace;opacity:.7}.case-count{padding:10px 16px;border-top:1px solid #e3eaf5;color:#8191a7}.case-detail{min-width:0;overflow:auto;overscroll-behavior:contain;padding:18px}.case-detail-header{display:flex;gap:14px;align-items:center}.case-detail-header>.el-input{flex:1;min-width:80px}.case-visibility,.case-help{font-size:12px;color:#7a8ba3;line-height:1.7;margin:10px 0 18px}.case-io{display:grid;grid-template-columns:1fr 1fr;gap:16px}.case-io label,.case-alternative label{min-width:0;font-weight:600;font-size:13px;color:#425a7b}.case-io small{float:right;color:#94a1b4;font-size:11px;font-weight:400}.case-io :deep(textarea),.case-alternative :deep(textarea){margin-top:9px;font:12px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;min-height:150px;background:#fbfcff;tab-size:4}.case-alternatives{margin-top:20px;padding-top:18px;border-top:1px solid #e4ebf5}.case-alternatives header{display:flex;align-items:center;justify-content:space-between;gap:10px}.case-alternatives strong{font-size:13px;color:#415a80}.case-alternatives p{font-size:12px;color:#8593a9;margin:6px 0}.case-alternative{display:flex;align-items:center;gap:12px;margin-top:14px}.case-alternative label{flex:1}.case-alternative :deep(textarea){min-height:70px}.case-empty,.case-empty-detail{font-size:13px;color:#8b9bb2;text-align:center;padding:24px 12px}.case-empty-detail{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px}.case-empty-detail p{margin:0 0 8px}.case-list button:focus-visible{outline:2px solid #5778ca;outline-offset:-2px}
@media(max-width:700px){.case-editor{grid-template-columns:145px minmax(0,1fr)}.case-browser-tools{padding:8px}.case-detail{padding:12px}.case-detail-header{flex-wrap:wrap;gap:8px}.case-detail-header>.el-input{flex-basis:100%}.case-io{grid-template-columns:1fr;gap:16px}.case-alternatives header{flex-wrap:wrap}.case-io :deep(textarea){min-height:120px}.case-list button{padding:9px 5px}.case-list strong{font-size:12px}}
@media(max-width:450px){.case-editor{display:flex;flex-direction:column}.case-browser{flex:none;max-height:160px;border-right:0;border-bottom:1px solid #e3eaf5}.case-browser-tools{display:flex}.case-list{display:flex;flex:none;overflow-x:auto;padding-bottom:6px}.case-list button{width:150px;flex:none;margin:0 4px}.case-count{display:none}.case-detail{flex:1;min-height:0}.case-empty-detail{flex:1}}
</style>
